CREATE TABLE defects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,unit_id uuid NOT NULL,subject text NOT NULL,location text NOT NULL,description text NOT NULL DEFAULT '',contractor_id uuid NOT NULL REFERENCES users(id),due_on date NOT NULL,status text NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','in_progress','review','accepted')),report text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id));
CREATE TABLE defect_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),defect_id uuid NOT NULL REFERENCES defects(id),actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER defect_history_guard BEFORE UPDATE OR DELETE ON defect_history FOR EACH ROW EXECUTE FUNCTION protect_request_history();
CREATE TABLE visitor_passes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,unit_id uuid NOT NULL,created_by uuid NOT NULL REFERENCES users(id),visitor text NOT NULL,vehicle text NOT NULL DEFAULT '',token_hash text NOT NULL UNIQUE,valid_from timestamptz NOT NULL,valid_until timestamptz NOT NULL,revoked_at timestamptz,state text NOT NULL DEFAULT 'expected' CHECK(state IN ('expected','inside','exited')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(valid_until>valid_from),FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id));
CREATE TABLE access_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pass_id uuid NOT NULL REFERENCES visitor_passes(id),actor_id uuid NOT NULL REFERENCES users(id),direction text NOT NULL CHECK(direction IN ('entry','exit')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER access_history_guard BEFORE UPDATE OR DELETE ON access_events FOR EACH ROW EXECUTE FUNCTION protect_request_history();
CREATE TABLE incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,building_id uuid NOT NULL,created_by uuid NOT NULL REFERENCES users(id),description text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(building_id,organization_id) REFERENCES buildings(id,organization_id));
CREATE TABLE support_access_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),support_user_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL,permission_keys text[] NOT NULL,requested_until timestamptz NOT NULL,approved_by uuid REFERENCES users(id),approved_at timestamptz,expires_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(approved_by IS NULL OR approved_by<>support_user_id));
INSERT INTO permissions(key) VALUES('access.create'),('support.access.approve') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_key,permission_key) VALUES('unit_owner','access.create'),('renter','access.create'),('org_admin','support.access.approve') ON CONFLICT DO NOTHING;
CREATE TABLE resident_delegations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),owner_assignment_id uuid NOT NULL REFERENCES role_assignments(id),unit_id uuid NOT NULL,permission_keys text[] NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,assignment_id uuid REFERENCES role_assignments(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id));
ALTER TABLE invitations ADD COLUMN delegation_id uuid REFERENCES resident_delegations(id);
CREATE UNIQUE INDEX delegation_assignment_unique ON resident_delegations(assignment_id) WHERE assignment_id IS NOT NULL;
